"""ElevenLabs Agents integration — live voice-call tracing.

Traces a voice call **as it happens**, rather than waiting for the call to end.
The ElevenLabs post-call webhook only fires once a conversation is finished, so
a call in progress is invisible to it; the Agent WebSocket, which the official
``elevenlabs`` Python SDK wraps in ``Conversation``, emits each turn live. This
module hooks those callbacks.

Turn -> step mapping follows ADR-0055 and reuses PRISMtrace's existing step
types rather than inventing voice-specific ones:

  callback_user_transcript   -> speech-to-text  (the caller's words)
  callback_agent_response    -> text-to-speech  (the agent's spoken reply)

Transcripts are posted to ``/api/voice/turns``, which scrubs PII server-side
before anything is persisted. Scrubbing deliberately does NOT happen here: this
module is a thin HTTP client and pushing Presidio into the SDK would make the
guarantee depend on the customer's install. Audio is never captured or sent.

Status: Supported. Uses the documented ``Conversation`` callback parameters —
``callback_user_transcript``, ``callback_agent_response`` and
``callback_agent_response_correction`` — not private internals.

Usage:

    from elevenlabs.client import ElevenLabs
    from elevenlabs.conversational_ai.conversation import Conversation
    from elevenlabs.conversational_ai.default_audio_interface import (
        DefaultAudioInterface,
    )
    from prismtrace import PRISMtraceVoiceTracer

    tracer = PRISMtraceVoiceTracer(
        api_key="pt-sk-...",
        project_id="<uuid>",
        agent_name="Support line",
    )

    conversation = Conversation(
        ElevenLabs(api_key=ELEVENLABS_API_KEY),
        AGENT_ID,
        requires_auth=True,
        audio_interface=DefaultAudioInterface(),
        **tracer.callbacks(),
    )

    conversation.start_session()
    conversation_id = conversation.wait_for_session_end()
    tracer.finalize(conversation_id)

**Choose one ingestion path per agent.** This live tracer and the post-call
webhook / connector both write the same call. Enabling both double-ingests it
under two ids. Use the tracer when you want to watch calls in flight; use the
webhook when post-call is sufficient.
"""
from __future__ import annotations


import threading
import uuid
from typing import Any, Callable, Optional

import httpx
from ._config import DEFAULT_HOST, resolve_host


_FRAMEWORK_TAG = "elevenlabs"
_DEFAULT_ENDPOINT = DEFAULT_HOST


class PRISMtraceVoiceTracer:
    """Forwards ElevenLabs conversation callbacks to PRISMtrace as voice steps.

    Thread-safe: the ElevenLabs SDK invokes callbacks from its own WebSocket
    thread, and turn ordering is what makes a trajectory readable, so the index
    counter is mutex-guarded.
    """

    def __init__(
        self,
        api_key: str,
        project_id: str,
        endpoint: Optional[str] = None,
        agent_name: str = "voice agent",
        agent_id: Optional[str] = None,
        conversation_id: Optional[str] = None,
        timeout: int = 10,
        on_error: Optional[Callable[[Exception], None]] = None,
    ) -> None:
        self.project_id = project_id
        self.endpoint = resolve_host(endpoint)
        self.agent_name = agent_name
        self.agent_id = agent_id
        self.on_error = on_error
        self.timeout = timeout

        # ElevenLabs only returns the real conversation id when the session
        # ends, but turns need a stable grouping key from the first callback.
        # A provisional id is used until finalize() supplies the real one.
        self._conversation_id = conversation_id or f"pending-{uuid.uuid4().hex[:12]}"
        self._provisional = conversation_id is None

        self._index = 0
        self._closed = False
        self._lock = threading.Lock()
        self._http = httpx.Client(
            headers={
                "X-PRISMtrace-Key": api_key,
                "Content-Type": "application/json",
            },
            timeout=timeout,
        )

    # ------------------------------------------------------------------
    # Public surface
    # ------------------------------------------------------------------

    def callbacks(self) -> dict:
        """Keyword arguments to splat into ``Conversation(...)``."""
        return {
            "callback_user_transcript": self.on_user_transcript,
            "callback_agent_response": self.on_agent_response,
            "callback_agent_response_correction": self.on_agent_response_correction,
        }

    @property
    def conversation_id(self) -> str:
        return self._conversation_id

    @property
    def session_id(self) -> str:
        return f"elevenlabs:{self._conversation_id}"

    def on_user_transcript(self, transcript: str) -> None:
        """Caller speech -> speech-to-text step."""
        self._emit("user", transcript)

    def on_agent_response(self, response: str) -> None:
        """Agent reply -> text-to-speech step."""
        self._emit("agent", response)

    def on_agent_response_correction(self, original: str, corrected: str) -> None:
        """The agent revised what it was going to say — usually a barge-in.

        Recorded as the corrected text, since that is what the caller actually
        heard. The superseded draft is not sent: it was never spoken.
        """
        self._emit("agent", corrected)

    def finalize(self, conversation_id: Optional[str]) -> dict:
        """Call with the return value of ``conversation.wait_for_session_end()``.

        Marks the call complete so it is sealed rather than left mid-flight. If
        the tracer was running under a provisional id, this reports the mapping
        so the live traces can be correlated with the ElevenLabs conversation.
        """
        mapping = {
            "traced_conversation_id": self._conversation_id,
            "elevenlabs_conversation_id": conversation_id,
            "session_id": self.session_id,
            "turns": self._index,
            "provisional": self._provisional,
        }
        # Zero-turn batch whose only job is to flip call_status to done.
        self._post(turns=[], status="done", start_index=self._index)
        return mapping

    def close(self) -> None:
        """Release the HTTP connection pool. Idempotent.

        Also available as a context manager, so a call can be traced without a
        try/finally around it.
        """
        if self._closed:
            return
        self._closed = True
        try:
            self._http.close()
        except Exception:
            pass

    def __enter__(self) -> "PRISMtraceVoiceTracer":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        self.close()
        return False

    # ------------------------------------------------------------------
    # Internals
    # ------------------------------------------------------------------

    def _emit(self, role: str, message: str) -> None:
        if not message:
            return
        with self._lock:
            index = self._index
            self._index += 1
        self._post(
            turns=[{"role": role, "message": message}],
            status="in-progress",
            start_index=index,
        )

    def _post(self, turns: list, status: str, start_index: int) -> None:
        payload = {
            "project_id": self.project_id,
            "conversation_id": self._conversation_id,
            "turns": turns,
            "status": status,
            "agent_id": self.agent_id,
            "agent_name": self.agent_name,
            "start_index": start_index,
        }
        try:
            response = self._http.post(f"{self.endpoint}/api/voice/turns", json=payload)
            response.raise_for_status()
        except Exception as exc:
            # Tracing must never break a live call. Same fail-open policy as
            # the LangChain and LiteLLM handlers.
            if self.on_error is not None:
                self.on_error(exc)
            else:
                print(f"[prismtrace {_FRAMEWORK_TAG}] turn forward failed: {exc}")


def install(
    conversation_kwargs: dict,
    api_key: str,
    project_id: str,
    **tracer_kwargs: Any,
) -> "PRISMtraceVoiceTracer":
    """Convenience entry point matching the other framework helpers.

    Merges the tracer callbacks into a ``Conversation(...)`` kwargs dict and
    returns the tracer so ``finalize()`` can be called at session end::

        kwargs = {"audio_interface": DefaultAudioInterface()}
        tracer = install(kwargs, api_key="pt-sk-...", project_id="<uuid>")
        conversation = Conversation(client, AGENT_ID, **kwargs)
    """
    tracer = PRISMtraceVoiceTracer(
        api_key=api_key, project_id=project_id, **tracer_kwargs
    )
    conversation_kwargs.update(tracer.callbacks())
    return tracer
